const MAX_READINGS = 500;
const UNITS = ["uV", "mV", "V"];

interface Signal {
  label: string;
  severity: number;
  alert: boolean;
}

// Bands are ordered by ascending maximum millivolts. A reading falls into the
// first band whose maximum it is strictly below; everything at or above the
// last threshold is critical.
const BANDS: Array<[max: number, label: string]>

  negative: { label: "negative", severity: 5, alert: true },
  standby: { label: "standby", severity: 0, alert: false },
  idle: { label: "idle", severity: 1, alert: false },
  active: { label: "active", severity: 2, alert: false },
  loaded: { label: "loaded", severity: 3, alert: true },
  critical: { label: "critical", severity: 4, alert: true },
};

// Single source of truth for naming, ranking, and alerting a millivolt value.
function signalFor(millivolts: number): Signal {
  for (const [max, label] of BANDS) {
    if (millivolts < max) {
      return SIGNALS[label];
    }
  }
  return SIGNALS.critical;
}

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
