 orig = require('./build_orig/_orig.js');
const neu = require('./build_new/process_batch.new.js');
const assert = require('assert');

function channel(c, u, v, at){ return {channel:c, unit:u, value:v, at}; }

const batches = [];
// invalid top-level
batches.push(null, 42, "str", undefined, {});
batches.push({readings: "no"});
batches.push({readings: []});
// too large
const big = {readings: []};
for(let i=0;i<501;i++) big.readings.push(channel("c","mV",1,i));
batches.push(big);
// bad entries
batches.push({readings:[channel("","mV",1,0)]});
batches.push({readings:[channel("c","XX",1,0)]});
batches.push({readings:[channel("c","mV",1.5,0)]});
batches.push({readings:[channel("c","mV",1,-1)]});
batches.push({readings:[channel("c","mV",1,"x")]});
batches.push({readings:[null, channel("c","mV",1,0)]});
// boundary millivolts via mV
function mv(v){ return channel("a","mV",v,0); }
batches.push({readings:[mv(-1),mv(0),mv(49),mv(50),mv(199),mv(200),mv(599),mv(600),mv(899),mv(900)]});
// unit conversion
batches.push({readings:[channel("a","V",1,0), channel("a","uV",100000,1), channel("a","uV",1000,2), channel("a","mV",5,3)]});
// multiple channels & worst tie
batches.push({readings:[channel("a","mV",100,0), channel("b","mV",700,0), channel("a","mV",-3,0), channel("b","mV",800,0), channel("c","mV",1000,0)]});
// single reading
batches.push({readings:[channel("only","mV",55,7)]});
// replicate 500 fine
const rep={readings:[]};
for(let i=0;i<500;i++) rep.readings.push(channel("ch"+i,"mV", i*2, i));
batches.push(rep);
// random
batches.push({readings:[
 channel("x","uV",999,0), channel("x","V",0,1), channel("y","mV",899,2), channel("y","mV",901,3), channel("z","mV",-5,4)
]});

let n=0;
for(const b of batches){
  const a = JSON.stringify(orig.processBatch(b));
  const c = JSON.stringify(neu.processBatch(b));
  assert.strictEqual(c, a, 'MISMATCH for batch '+n+'\n'+c+'\n'+a);
  n++;
}
// exhaustively check classifySignal over the whole integer domain boundary region
for(let v=-1000;v<=1500;v++){
  assert.strictEqual(neu.classifySignal(v), orig.classifySignal(v), 'classify '+v);
}
console.log('ALL ' + n + ' batches + classify domain MATCH');
